"""Roman numerals for 1..3999."""

_PAIRS = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
    (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]


def to_roman(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(f"not an integer: {n!r}")
    if not 1 <= n <= 3999:
        raise ValueError(f"out of range (1..3999): {n}")
    out = []
    for value, sym in _PAIRS:
        while n >= value:
            out.append(sym)
            n -= value
    return "".join(out)


def from_roman(s):
    if not isinstance(s, str):
        raise ValueError(f"not a string: {s!r}")
    i, total = 0, 0
    for value, sym in _PAIRS:
        while s.startswith(sym, i):
            total += value
            i += len(sym)
    if i != len(s) or total == 0 or to_roman(total) != s:
        raise ValueError(f"not a canonical roman numeral: {s!r}")
    return total
